/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
[ExtensionOf(classStr(GUPPriceReportTask))]
final class METPriceReportTask_Extension
{
    
}

Method.Source:
    /// <summary>
    /// essentially a copy of GUPPriceReportTask.execute() which is marked Private and cant be used here
    /// </summary>
    public void executeTask()
    {
        System.Exception metEx;

        ListIterator metIterator = new ListIterator(customerList);

        while (metIterator.more())
        {
            AccountNum metCustomerId = metIterator.value();

            try
            {
                this.calculatePriceListDetails(metCustomerId, this.parmSessionGuid());
            }
            catch (metEx)
            {
                warning(strFmt("@GlobalUnifiedPricing:GUPPriceReportGenerateEngineCustomerException", metCustomerId));
                warning(metEx.Message);
            }
            finally
            {
                metIterator.next();
            }
        }

    }

/// <summary>
/// Work around to call deleteFindPriceTasks() which is marked as Protected
/// </summary>
public void metDeleteFindPriceTasks()
{
    this.deleteFindPriceTasks();
}

    /// <summary>
    /// Essentially a Copy of GUPPriceReportGenerateEngine.populatePriceReportResult(). 
    /// Populate Extract table instead of Report result table.
    /// </summary>
    public void metPopulatePriceDataExtract()
    {
        GUPTmpPriceReportValues     metTmpPriceReportValues;
        METPriceDataExtract         metPriceDataExtract;
        METEntryId                  metEntryId;
        NumberSequenceReference     metNumberSequenceReference;
        NumberSeq                   metNumberSeq;        

        metNumberSequenceReference = GUPParameters::numRefMETEntryId();
        
        if (metNumberSequenceReference)
        {
            metNumberSeq = NumberSeq::newGetNum(metNumberSequenceReference);
        }

        if(!metNumberSeq)
        {
            error("@MET:EntryNumberIdNumSeqFailed");
            throw Exception::Error;
        }

        if (userConnection)
        {
            metTmpPriceReportValues.setConnection(userConnection);
            metPriceDataExtract.setConnection(userConnection);
        }

        Map metPriceListToBeKept = new Map(Types::Int64, Types::Container);

        while select minof(FromDate), maxof(ToDate), minof(RecId) 
            from metTmpPriceReportValues
            group by metTmpPriceReportValues.AccountNum, metTmpPriceReportValues.CurrencyCode, metTmpPriceReportValues.ItemId, metTmpPriceReportValues.VariantId,
                    metTmpPriceReportValues.BasePrice, metTmpPriceReportValues.TAJournalNum,
                    metTmpPriceReportValues.MarginOffers, metTmpPriceReportValues.MarginAmountList, metTmpPriceReportValues.CalculatedMargin,
                    metTmpPriceReportValues.DiscountOffers, metTmpPriceReportValues.DiscountAmountList, metTmpPriceReportValues.CalculatedDiscount,
                    metTmpPriceReportValues.UnitPrice, metTmpPriceReportValues.SalesPrice, metTmpPriceReportValues.LineAmount
            where metTmpPriceReportValues.ReportId == this.parmSessionGuid()
        {
            metPriceListToBeKept.add(metTmpPriceReportValues.RecId, [metTmpPriceReportValues.FromDate, metTmpPriceReportValues.ToDate]);
        }

        RecordInsertList metListOfPriceDataExtract = new RecordInsertList(tableNum(METPriceDataExtract));

        ValidFromDate   metFromDate;
        ValidToDate     metToDate;
        RecId           metPriceValueRecId;
        GUPTmpPriceReportValues metTmpFinalPriceReportValues;

        MapEnumerator   metEnumerator = metPriceListToBeKept.getEnumerator();
        
        while (metEnumerator.moveNext())
        {
            metPriceValueRecId          = metEnumerator.currentKey();
            [metFromDate, metToDate]    = metEnumerator.currentValue();

            select firstonly metTmpFinalPriceReportValues
                where metTmpFinalPriceReportValues.RecId == metPriceValueRecId;

            metPriceDataExtract.clear();
            metPriceDataExtract.EntryNumber     = str2Int64(metNumberSeq.num());
            metPriceDataExtract.taskGuid        = this.parmSessionGuid();

            metPriceDataExtract.initFromTmpPriceList(metTmpFinalPriceReportValues);

            metListOfPriceDataExtract.add(metPriceDataExtract);
        }

        ttsbegin;
        metListOfPriceDataExtract.insertDatabase();
        ttscommit;
    }
